      targetProfitPerMile: dataset.goals.targetProfitPerMile,
      maxDeadheadPct: dataset.goals.maxDeadheadPct,
      targetLoads: dataset.goals.targetLoads,
      workingDaysPerWeek: dataset.goals.workingDaysPerWeek,
